signals = ['SJ', 'FK', 'logprob', 'EM', 'voting_conf']

def build_3seed_section(seeds_data):
    section = {'ner': {'full': {}, 'conditional': {}}}
    for sig in signals:
        for eval_type in ['full', 'conditional']:
            vals = [seeds_data[s][eval_type][sig] for s in ['seed42', 'seed123', 'seed456']]
            section['ner'][eval_type][sig] = {
                'seeds': vals,
                'mean': round(float(np.mean(vals)), 4),
                'sd': round(float(np.std(vals, ddof=1)), 4),
                'cv_pct': round(float(np.std(vals, ddof=1) / abs(np.mean(vals)) * 100), 1)
            }
    return section

